begin;
do $test$
declare shop uuid; settings jsonb=$settings${"businessName":"Dropdown QA","address":"","phones":"","email":"","website":"","socials":"","logo":"","primary":"#124b40","accent":"#d9a126","theme":"system","options":{"paymentMethods":[{"label":"Cash","kind":"Cash","enabled":true},{"label":"POS","kind":"POS","enabled":true},{"label":"Transfer","kind":"Transfer","enabled":true},{"label":"Opay","kind":"Transfer","enabled":true}],"expenseCategories":["Materials","Electricity","Fuel","Rent","Wages","Maintenance","Delivery","Outsourcing","Internet / phone","Other"],"jobSources":["In shop / USB","Shop network","WhatsApp","Email","Other"],"stockReasons":["Restocking","Stock Count Correction","Returned Stock","Damaged Stock"],"materialUnits":["sheet","piece","metre","square metre","roll","kilogram","litre"],"jobStages":["Added","Design","Approval","Finishing","Completed","Collected"]},"receipt":{"showLogo":true,"showAddress":true,"showContacts":true,"footer":"Thank you for your business."}}$settings$; operation jsonb=$event${"id":"50000000-0000-4000-8000-000000000001","kind":"checkout.completed","data":{"id":"50000000-0000-4000-8000-000000000001","customerId":"20000000-0000-4000-8000-000000000001","newCustomer":null,"customerSnapshot":{"id":"20000000-0000-4000-8000-000000000001","name":"Customer","phone":"080111","address":"Road"},"jobBalances":[{"id":"30000000-0000-4000-8000-000000000001","description":"Artwork","service":"Design","amount":10000,"paidBefore":0,"paidThisCheckout":10000,"outstandingAfter":0}],"jobs":[{"id":"30000000-0000-4000-8000-000000000001","serviceId":"40000000-0000-4000-8000-000000000001","description":"Artwork","quantity":1,"source":"Instagram DM","sourceNote":"","workflow":["Added","Design","Approval","Finishing","Completed","Collected"],"width":null,"height":null,"amount":10000,"unitPrice":10000,"service":"Design","materialId":null,"materialNeeded":0,"measurementUnit":"item","requireSize":false,"serviceVersion":1,"customerId":"20000000-0000-4000-8000-000