begin
insert into auth.users(id,email,raw_user_meta_data,created_at)values('10000000-0000-4000-8000-000000000001','business-options-qa@example.invalid','{}',now());
perform set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);shop:=public.create_shop('Dropdown QA');
perform public.save_business_settings(shop,0,settings);
begin perform public.save_business_settings(shop,1,jsonb_set(settings,'{options,expenseCategories}','["Fuel"," fuel "]'));raise exception 'Duplicate category accepted';exception when others then if sqlerrm='Duplicate category accepted' then raise;end if;end;
begin perform public.save_business_settings(shop,1,jsonb_set(settings,'{options,paymentMethods}','[{"label":"Opay","kind":"Other","enabled":true}]'));raise exception 'Unknown accounting accepted';exception when others then if sqlerrm='Unknown accounting accepted' then raise;end if;end;
perform public.apply_customer_event(shop,jsonb_build_object('id',gen_random_uuid(),'kind','customer.created','data',jsonb_build_object('id','20000000-0000-4000-8000-000000000001','name','Customer','phone','080111','address','Road','creditLimit',0,'modifiedBy','10000000-0000-4000-8000-000000000001')));
perform public.apply_service_event(shop,jsonb_build_object('id',gen_random_uuid(),'kind','service.created','data',jsonb_build_object('id','40000000-0000-4000-8000-000000000001','description','Design','materialId',null,'price',10000,'modifiedBy','10000000-0000-4000-8000-000000000001')));
perform public.apply_checkout_event(shop,operation);perform public.apply_checkout_event(shop,operation);
snapshot:=public.get_ledger(shop);
if snapshot->'checkouts'->0->>'methodLabel'<>'Opay' or snapshot->'payments'->0->>'methodLabel'<>'Opay' or snapshot->'jobs'->0->>'source'<>'Instagram DM' then raise exception 'Custom dropdown details lost';end if;
if (select sum(amount) from public.payments where shop_id=shop and method='Transfer')<>10000 or (select count(*) from public.payments where shop_id=shop)<>1 then raise exception 'Alias changed totals or retry duplicated payment';end if;
perform public.save_business_settings(shop,1,jsonb_set(settings,'{options,jobStages}','["Added","Printing","Completed","Collected"]'));
begin perform public.apply_job_status_event(shop,jsonb_build_object('id',gen_random_uuid(),'kind','job.status_changed','data',jsonb_build_object('id','30000000-0000-4000-8000-000000000001','baseVersion',1,'status','Completed','modifiedBy','10000000-0000-4000-8000-000000000001')));raise exception 'Skipped workflow accepted';exception when sqlstate 'PT409' then null;end;
foreach stage in array array['Design','Approval','Finishing','Completed','Collected'] loop
 perform public.apply_job_status_event(shop,jsonb_build_object('id',gen_random_uuid(),'kind','job.status_changed','data',jsonb_build_object('id','30000000-0000-4000-8000-000000000001','baseVersion',version,'status',stage,'modifiedBy','10000000-0000-4000-8000-000000000001')));version:=version+1;
end loop;
if (select production_status from public.jobs where shop_id=shop)<>'Collected' then raise exception 'Original workflow lost after settings edit';end if;
perform public.apply_expense_event(shop,jsonb_build_object('id',gen_random_uuid(),'kind','expense.created','data',jsonb_build_object('id',gen_random_uuid(),'description','Delivery','category','Custom category','incurredOn','2026-10-08','amount',10000,'payee','','note','','receiptReference','','materials','[]'::jsonb,'stockIds','{}'::jsonb,'modifiedBy','10000000-0000-4000-8000-000000000001','modifiedByLabel','Manager','modifiedAt',now(),'payment',jsonb_build_object('id',gen_random_uuid(),'amount',10000,'paidOn','2026-10-08','method','Transfer','methodLabel','Opay','source','Business bank account','reference',''))));
if (select data->'payments'->0->>'methodLabel' from public.expenses where shop_id=shop)<>'Opay' then raise exception 'Expense method label lost';end if;
perform set_config('business_options.test_shop',shop::text,true);
end $test$;
set local role authenticated;
do $$declare shop uuid:=current_setting('business_options.test_shop')::uuid;settings jsonb;begin
select b.settings into settings from public.business_settings b where shop_id=shop;
perform public.save_business_settings(shop,2,settings);
if public.get_ledger(shop)->'payments'->0->>'methodLabel'<>'Opay' then raise exception 'Authenticated payment label unavailable';end if;
end $$;
